function ownCertificate(stored:typeof TARGETS[number]['certificate']):ReviewedU7049GrowingCertificate{ensure(stored.initialSufficientConditions&&stored.syntax==='MQ'&&stored.initialKind==='single-quadratic','灉 own grammar certificate kind');return deepFreeze({syntax:stored.syntax as 'MQ'|'MC',initialKind:stored.initialKind as 'single-quadratic'|'single-cubic',T:'T'in stored?stored.T:null,K:stored.K,firstLegLength:'firstLegLength'in stored?stored.firstLegLength:null,initialArcMax:stored.initialArcMax as 1|7,storedBounds:stored,notRasterProof:true as const,notPreviousMaskConnectivityProof:true as const,notFullSweepProof:true as const})}
